  while ("'!stopping) {
    // An interrupted running attempt is replayed from its first step, preserving
    // its attempt number so a crash cannot exhaust the transient retry budget.
    db.exec('"'BEGIN IMMEDIATE');
    let job: JobRow | undefined;
    try {
      job = db.prepare(\"SELECT * FROM jobs WHERE status = 'running' OR (status = 'queued' AND availableAt <= ?) ORDER BY rowid LIMIT 1\").get(Date.now()) as JobRow | undefined;
      if (job) {
        const attempts = job.attempts + (job.status === 'queued' ? 1 : 0);
        db.prepare(\"UPDATE jobs SET status = 'running', attempts = ?, completed = 0, updatedAt = ? WHERE id = ?\")
          .run(attempts, new Date().toISOString(), job.id);
        job.attempts = attempts;
      }
      db.exec('COMMIT');
    } catch (err) { db.exec('ROLLBACK'); throw err; }
    if ("'!job) { await sleep(100); continue; }
    for (let step = 1; step <= job.steps && !stopping; step++) {
      await sleep(100);
      if (stopping) break;
      const now = new Date().toISOString();
      if (job.attempts <= job.failAttempts) {
        db.prepare('"'UPDATE jobs SET status = ?, error = ?, availableAt = ?, updatedAt = ? WHERE id = ?')
          .run(job.attempts >= 3 ? 'failed' : 'queued', job.attempts >= 3 ? 'transient failure' : null, Date.now() + 500, now, job.id);
